  `TYPE` int NOT NULL,
  `gender` smallint NOT NULL,
  `NAME` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `level` int NOT NULL DEFAULT '0',
  `icon_id` int NOT NULL,
  `part` int NOT NULL,
  `is_up_to_up` tinyint(1) NOT NULL,
  `power_require` bigint NOT NULL,
  `gold` int NOT NULL DEFAULT '0',
  `gold_sell` int NOT NULL DEFAULT '0',
  `gem` int NOT NULL DEFAULT '0',
  `gem_sell` int NOT NULL DEFAULT '0',
  `ruby` int NOT NULL DEFAULT '0',
  `ruby_sell` int NOT NULL DEFAULT '0',
  `head` int NOT NULL DEFAULT '-1',
  `body` int NOT NULL DEFAULT '-1',
  `leg` int NOT NULL DEFAULT '-1',
  `TypeEvent` int NOT NULL DEFAULT '0',
  `isGender` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
