  PRIMARY KEY (`idmain`) USING BTREE,
  KEY `task_main_id` (`task_main_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=271 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
